<script setup lang="ts">
import {computed,ref,onMounted,onUnmounted,watch} from 'vue';
import QuestionBank from './QuestionBank.vue';import ReadingPractice from './ReadingPractice.vue';import ReadingRecords from './ReadingRecords.vue';import ReadingWordBank from './ReadingWordBank.vue';import VocabularyPanel from '../App.vue';
import {loadCatalog,loadExam} from './repository';import {readingHistory,readingWords,readingStorageWarning} from './storage';
import type {CatalogEntry,ReadingExam,ReadingRecord} from './model';
import './reading.css';
const route=ref(location.hash.slice(1)||'library');const page=computed(()=>route.value.split('/')[0]);const id=computed(()=>route.value.split('/')[1]||'');
const catalog=ref<CatalogEntry[]>([]);const catalogReady=ref(false);const error=ref('');const loading=ref(false);const exam=ref<ReadingExam>();const record=ref<ReadingRecord>();let loadVersion=0;
function navigate(value:string){if(location.hash===`#${value}`)route.value=value;else location.hash=value;}
function locationChanged(){route.value=location.hash.slice(1)||'library';}
async function catalogLoad(){try{catalog.value=await loadCatalog();catalogReady.value=true;}catch(e){error.value=(e as Error).message;}}
async function activate(){const version=++loadVersion;error.value='';exam.value=undefined;record.value=undefined;document.title='IELTS Practice';if(page.value==='practice'||(page.value==='records'&&id.value)){loading.value=true;try{if(page.value==='records'){const found=readingHistory.value.find(r=>r.id===id.value);if(!found)throw new Error('这条练习记录不存在或已删除。');record.value=found;exam.value=found.exam;}else {const loaded=await loadExam(id.value);if(version!==loadVersion)return;exam.value=loaded;}if(version!==loadVersion)return;document.title=`${exam.value?.title} · IELTS Practice`;}catch(e){if(version===loadVersion)error.value=(e as Error).message;}finally{if(version===loadVersion)loading.value=false;}}else{loading.value=false;if(!['library','words','wordbank','records','sources'].includes(page.value))navigate('library');}window.scrollTo({top:0});}
watch(route,activate);onMounted(()=>{window.addEventListener('hashchange',locationChanged);void catalogLoad();void activate();});onUnmounted(()=>window.removeEventListener('hashchange',locationChanged));
const active=computed(()=>['practice','library'].includes(page.value)?'library':page.value==='wordbank'?'words':page.value);
const tabs=[{id:'library',label:'阅读题库'},{id:'words',label:'单词练习'},{id:'wordbank',label:'阅读生词'},{id:'records',label:'练习记录'},{id:'sources',label:'资源来源'}];
</script>
<template><div class="rp-root"><a class="rp-skip" href="#rp-main" @click.prevent="($refs.main as HTMLElement)?.focus()">跳到主要内容</a><div class="rp-shell"><header class="rp-site-header"><a class="rp-brand" href="#library">IELTS Practice</a><span class="rp-site-caption">阅读，让词汇有语境。</span></header><nav class="rp-main-nav" aria-label="主导航"><a v-for="tab in tabs" :key="tab.id" :href="`#${tab.id}`" :aria-current="(tab.id==='wordbank'?page==='wordbank':tab.id===active&&page!=='wordbank')?'page':undefined">{{tab.label}}<span v-if="tab.id==='wordbank'&&readingWords.length" class="rp-count">{{readingWords.length}}</span></a></nav><main id="rp-main" ref="main" tabindex="-1"><p v-if="readingStorageWarning" class="rp-notice error" role="alert">{{readingStorageWarning}}</p><div v-if="error" class="rp-panel" role="alert"><h1>暂时无法打开内容</h1><p>{{error}}</p><button class="rp-button secondary" @click="catalogReady?activate():catalogLoad()">重试</button> <button class="rp-button" @click="navigate('library')">返回题库</button></div><div v-else-if="loading" class="rp-panel rp-empty" role="status">正在加载文章与题目…</div><ReadingPractice v-else-if="exam" :key="route" :exam="exam" :record="record" @back="navigate('library')"/><QuestionBank v-else-if="page==='library'&&catalogReady" :catalog="catalog" @start="navigate(`practice/${$event}`)"/><div v-else-if="page==='library'" class="rp-panel rp-empty" role="status">正在加载阅读题库…</div><div v-else-if="page==='words'" class="rp-panel rp-vocabulary"><VocabularyPanel :key="route" :initial-list="id==='reading'?'reading':undefined"/></div><ReadingWordBank v-else-if="page==='wordbank'" @practice="navigate('words/reading')" @reading="navigate(`practice/${$event}`)"/><ReadingRecords v-else-if="page==='records'" @open="navigate(`records/${$event}`)"/><section v-else-if="page==='sources'" class="rp-panel rp-sources"><span class="rp-eyebrow">CONTENT & IMPLEMENTATION</span><h1>资源来源与实现说明</h1><h2>文章和题目</h2><p>内置 {{catalog.length||238}} 篇文章与试题取自项目既有的阅读资源，内容沿用原数据，逐篇保留资源路径作为来源参考。它们不是本次重新编写的文章，也不统一标记为 IELTS 官方真题；原作者、出版物及题目年份需另行核实。</p><p><a href="https://github.com/sallowayma-git/IELTS-practice" target="_blank" rel="noopener noreferrer">既有阅读资源项目 ↗</a></p><h2>词库与词典</h2><p>核心词库沿用项目既有 IELTS 词汇数据；阅读选词释义优先使用本地词典，可根据文章语境手动修改。</p><a href="https://github.com/skywind3000/ECDICT" target="_blank" rel="noopener noreferrer">ECDICT 词典数据来源 ↗</a><h2>本次重新实现的功能</h2><p>Vue 页面、JSON 题库适配、题库检索与导入编辑、文章展示、答题控件、判分、草稿与练习记录、阅读选词收藏及词汇练习联动。新版不加载旧阅读模块的界面和业务脚本。</p><h2>本地数据</h2><p>新版阅读数据保存在当前浏览器，通过导出功能备份。旧版 IndexedDB 与历史备份文件不会被覆盖，也未自动转为新版记录。单词练习继续使用原来的学习进度。</p></section></main><footer class="rp-footer">IELTS Practice <span>阅读 · 词汇 · 持续积累</span></footer></div></div></template>
